<?php require __DIR__.'/../bootstrap.php';require_login();$id=current_user()['id'];$nid=(int)getv('id');$s=db()->prepare('SELECT * FROM notes WHERE id=? AND user_id=?');$s->execute([$nid,$id]);$n=$s->fetch();if(!$n)exit('Note not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE notes SET title=?,content=?,is_pinned=?,updated_at=NOW() WHERE id=? AND user_id=?')->execute([post('title'),post('content'),post('pinned')?1:0,$nid,$id]);redirect('/notes/');}$title='Edit Note';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Title<input name="title" value="<?=e($n['title'])?>" required></label><label>Content<textarea name="content" rows="16"><?=e($n['content'])?></textarea></label><label class="check"><input type="checkbox" name="pinned" value="1" <?=$n['is_pinned']?'checked':''?>> Pin note</label><div class="actions"><button class="btn edit-btn" style="background:var(--brand)!important;color:#fff!important">Save Changes</button><button class="btn danger" type="submit" formaction="/notes/delete/" formmethod="post" name="id" value="<?=$nid?>">Delete Note</button></div><p><a class="btn secondary small" href="/ai/?prompt=Note%20assist%3A%20help%20me%20improve%20this%20note">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>